package app

import (
	"errors"
	"log"
	"net"
	"net/http"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	mcpserver "github.com/anthnel/devdesk/internal/mcp"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/configuration"
)

// MCPServerStartedMsg reports what became of the attempt to serve MCP.
//
// It is a message and not a return value because opening a listener is I/O, and
// I/O belongs in a Cmd (Rule 110). Addr is what the listener actually bound —
// not what the setting asked for — so a port chosen by the OS would be reported
// truthfully; Err is why there is nothing listening.
type MCPServerStartedMsg struct {
	// Epoch is which start this reports. A switch made while an earlier start
	// is still in flight — ResolveToken can block on a locked keyring, or on a
	// two-second `git config` read — would otherwise have the old start's
	// message land afterwards and store its server, leaving a listener still
	// answering for the context nobody is in while the new one fails to bind.
	// That is exactly the guarantee the restart exists to give.
	Epoch  uint64
	Addr   string
	Server *http.Server
	Err    error
	// Token is the bearer an agent has to present. It is carried here so the
	// configuration view can show it — the one screen where somebody goes
	// looking for it — and it lives in the secret store, never in a file
	// DevDesk writes (§3.9).
	Token string
}

// startMCPCmd is a method so it reads the router's config, context and secret
// store; those three are copied into the closure rather than read from the
// receiver inside it, because a Cmd runs on its own goroutine and the receiver
// is the model (Rule 110).

// startMCPCmd serves this context over MCP, or explains why it does not.
//
// Nothing is attempted when the context has not enabled it: the refusal is
// carried on the message rather than logged and dropped, because "off" and
// "could not bind" look identical from the outside and only one of them is a
// problem.
//
// The listener is opened here, inside the Cmd, and handed back on the message.
// That is the same shape as a scan's context.CancelFunc travelling on its
// starting message: the thing is created where the I/O happens and stored by
// the one place allowed to store it.
func (a *App) startMCPCmd() tea.Cmd {
	a.mcpEpoch++
	epoch := a.mcpEpoch
}

// restartMCPCmd serves the context now on screen, and stops serving the one that
// was (§3.61).
//
// The server is built around one Env — a config and a context name captured
// when it starts — so a switch that left it running would keep answering for
// the context nobody is in any more. Rebuilding is not a nicety here; not doing
// it is the bug.
//
// **The restart drops the open MCP sessions, and that is the guarantee, not a
// side effect.** §3.38 fixed the context at process start precisely so it could
// not change underneath an agent mid-conversation; §3.61 gives that up, and
// what replaces it is this — a client does not silently start reading another
// context, it loses its session and re-initialises. The alternative on offer
// was a notification, and the SDK only delivers one if the client has set a log
// level, which is a guarantee that holds when it feels like it.
//
// Switching to a context with `mcp.enabled: false` therefore stops the server:
// the setting is per context, and a server outliving the context that allowed
// it would be the one way to serve a context that said no.
func (a *App) restartMCPCmd() tea.Cmd {
	srv := a.mcpServer
	a.mcpServer = nil
	a.mcpAddr = ""
	a.mcpErr = nil
	a.mcpToken = ""

	start := a.startMCPCmd()
	if srv == nil {
		return start
	}
	return tea.Sequence(
		func() tea.Msg {
			// Close rather than Shutdown: an agent's request in flight belongs
			// to the context being left, and letting it finish would answer for
			// that context after the user has moved on — which is the thing
			// this restart exists to prevent.
			_ = srv.Close()
			return nil
		},
		start,
	)
}

// handleMCPServerStarted stores the running server, or records why there is
// none.
//
// Both outcomes are kept. A view that wants to tell the user where to point an
// agent needs the address; one that wants to say why nothing is listening needs
// the error, and "the setting is off" is one of the answers rather than the
// absence of one.
func (a *App) handleMCPServerStarted(msg MCPServerStartedMsg) (tea.Model, tea.Cmd) {
	// A report from a start the session has moved past. Its listener, if it got
	// one, is closed here rather than stored: storing it would leave a server
	// answering for a context nobody is in, and dropping it silently would leak
	// the port the current context is trying to bind.
	if msg.Epoch != a.mcpEpoch {
		if msg.Server != nil {
			log.Printf("MCP server for a superseded context closed on arrival (epoch %d, now %d)", msg.Epoch, a.mcpEpoch)
			_ = msg.Server.Close()
		}
		return a, nil
	}

	a.mcpServer = msg.Server
	a.mcpAddr = msg.Addr
	a.mcpErr = msg.Err
	a.mcpToken = msg.Token

	// The configuration view shows all three, and it is built lazily — so drop
	// the cached one and let it be rebuilt with what is now true. The precedent
	// is useSecrets rebuilding the auth view when the store is resolved.
	//
	// Rebuilt at once when it is the screen the user is on, and not merely
	// dropped: renderBody falls back to "View not found: configuration" for a
	// currentView with no entry, and keys.go routes nothing to it — the user
	// would sit on a dead screen until they retyped `:config`. Reachable two
	// ways: `app.default_view: configuration` plus the startup report, which
	// fires even when the server is off, and a context switch made while
	// sitting in that view.
	if _, cached := a.views[command.ViewConfiguration]; cached {
		delete(a.views, command.ViewConfiguration)
		if a.currentView == command.ViewConfiguration {
			a.createView(command.ViewConfiguration)
			a.resize(a.width, a.height)
		}
	}

	if msg.Err != nil {
		log.Printf("MCP server not serving context %q: %v", a.currentContext, msg.Err)
		// Only when the context asked for a server. Nothing was attempted
		// otherwise, so there is nothing to report, and a message announcing
		// the failure of a server nobody asked for reads as a fault (§3.61).
		//
		// Rule 128 calls this an Error and not a Warn: the bind was refused,
		// which is the system saying no, not an action that cannot be honoured
		// as asked. The commonest cause is a second `dk` already holding the
		// port — the TUI keeps running without a server, because losing the
		// application over a taken port would be out of all proportion.
		if !a.config.MCP.Enabled {
			return a, nil
		}
		return a, components.PostFooter(components.LevelError, "MCP server not started — "+msg.Err.Error())
	}
	log.Printf("MCP server for context %q listening on %s", a.currentContext, msg.Addr)
	return a, nil
}

// mcpFacts is what the configuration view shows about the server: where it
// listens, the bearer an agent needs, or why there is nothing.
//
// The refusal is rendered rather than the error value, because "the setting is
// off" is one of the answers and reads as a state, not a fault.
func (a *App) mcpFacts() configuration.MCPFacts {
	facts := configuration.MCPFacts{Addr: a.mcpAddr, Token: a.mcpToken}
	if a.mcpErr != nil && a.config.MCP.Enabled {
		facts.Reason = a.mcpErr.Error()
	}
	return facts
}
