// ConfigSavedMsg tells the router the context's configuration changed on disk.
//
// BackendChanged is separate from "something changed" because it is the one
// setting the router cannot honour by rebuilding views: it has to resolve a new
// credentials.Selection first.
type ConfigSavedMsg struct {
	Config       *config.Config
	ThemeChanged bool
	// BackendChanged, ForgeChanged and EngineChanged are the settings the
	// router must act on rather than just rebuild views against: the first
	// needs a fresh credentials.Selection, the second invalidates a live forge
	// session, the third has to re-resolve the container engine before any
	// rebuilt view asks it anything.
	//
	// ForgeChanged is one flag for two settings — the URL and the platform —
	// because the consequence is one: the session was opened against something
	// the config no longer describes.
	BackendChanged bool
	ForgeChanged   bool
	EngineChanged  bool
}

// Model is the configuration view: every scalar setting in the current context,
// grouped into tabs.
//
// Tabs are not decoration. Twenty-nine fields in one list is unusable, and
// under Rule 135 a tabbed form is the only layout that uses the keyboard
// correctly: Tab is reserved for tabs and ↑↓ for fields, so each key has
// exactly one job.
type Model struct {
	config   *config.Config
	context  string
	sections []section

	activeTab    int
	focusedField int

	// input is bound to the focused text or integer field. There is one, not one
	// per field: the value is read from the config on focus and written back on
	// blur, so the input is a view onto the setting rather than a second copy of
	// it.
	input textinput.Model

	// forgeOnFocus is what forge.type held when the field took focus, and
	// forgeTouched whether the user has ever moved it. The second is what stops
	// host detection overwriting an explicit choice — the difference between
	// helpful and possessive.
	forgeOnFocus string
	forgeTouched bool

	// themes and configPath are kept because the field table is rebuilt when
	// the forge changes: its title, its icon and half its options come from the
	// platform, and the router keeps this view on a save.
	themes     []string
	configPath string

	// mcp is what the router knows about the MCP server — where it listens, its
	// token, or why there is none. It is passed in rather than read here
	// because only the router has it, and the view is rebuilt when it changes.
	mcp MCPFacts

	// shown holds the secret rows the user has revealed, keyed by label: the
	// field table is rebuilt on every save, so an index would point elsewhere
	// afterwards.
	shown map[string]bool

	// engineOnFocus is what app.container_engine held when the field took
	// focus. Cycling auto → docker → podman must re-resolve once, on the way
	// out, not once per keypress — the forge field's reasoning exactly.
	engineOnFocus string

	// backendOnFocus is what app.secret_backend held when the field took focus.
	// Changing it is confirmed on the way out rather than on every ←/→, and this
	// is what "No" restores.
	backendOnFocus string
	confirmModal   *sharedcomponents.ConfirmModal

	// footer is the one line of transient state below the tab bar (Rule 128).
	footer sharedcomponents.FooterMessage

	// tools is the router's detection of the scanners (§3.86), nil until it
	// lands. The tools tab reads it; it never runs one itself.
	tools *scan.Report

	// scroll is the first line of the tab on screen. A tab taller than the
	// viewport scrolls so the focused field stays visible.
	scroll int

	width  int
	height int
}

// New builds the view for the configuration currently loaded.
// MCPFacts is what the configuration view shows about the MCP server.
//
// Three states and they are all worth saying: an address means it is serving,
// a reason means it is not and why, and neither means the context has not asked
// for one. Nothing here is editable — `mcp.enabled` and `mcp.listen` are the
// settings; this is what became of them.
type MCPFacts struct {
	Addr   string
	Token  string
	Reason string
}

func New(cfg *config.Config, mcp MCPFacts) Model {
	themes, err := theme.ListThemes()
	if err != nil || len(themes) == 0 {
		// A theme directory that cannot be read still leaves the built-in one, so
		// the cycle has something to offer rather than nothing.
		log.Printf("ERROR [configuration] list themes: %v", err)
		themes = []string{"default"}
	}

	in := textinput.New()
	in.CharLimit = 512
	theme.StyleTextInput(&in)

	context := config.CurrentContextName()

	// A home directory that cannot be resolved leaves the row empty rather than
	// absent: the label still says which fact is missing.
	configPath, err := config.GetContextPath(context)
	if err != nil {
		log.Printf("ERROR [configuration] resolve context path for %s: %v", context, err)
	}

	m := Model{
		config:       cfg,
		context:      context,
		sections:     sections(themes, command.ViewNames(), configPath, context, cfg.Forge.Type, forge.VocabularyFor(cfg.Forge.Type), mcp),
		input:        in,
		themes:       themes,
		configPath:   configPath,
		mcp:          mcp,
		shown:        map[string]bool{},
		forgeOnFocus: cfg.Forge.Type,
	}
	m.bindInput()
	return m
}

// Init satisfies tea.Model. Nothing is loaded asynchronously: the configuration
// is already in memory, which is what makes this view open on its first frame.
func (m Model) Init() tea.Cmd { return nil }

// InEditMode reports whether a text field or the confirm modal has the
// keyboard, which is what stops the router claiming ":", "q" and "?".
func (m Model) InEditMode() bool {
	return m.confirmModal != nil || m.current().takesText()
}

// current returns the focused field.
func (m Model) current() field {
	fields := m.fields()
	if m.focusedField < 0 || m.focusedField >= len(fields) {
		return field{}
	}
	return fields[m.focusedField]
}

// fields returns the active tab's fields.
func (m Model) fields() []field {
	if m.activeTab < 0 || m.activeTab >= len(m.sections) {
		return nil
	}
	return m.sections[m.activeTab].Fields
}

// takesText reports whether a field is edited by typing.
func (f field) takesText() bool {
	return f.Kind == kindText || f.Kind == kindInteger
}

// focusable reports whether the cursor may stop on a field. A static row is the
// one that answers no: there is nothing to type, cycle or toggle on it, and a
// focus indicator on a row no key acts upon says the opposite.
func (f field) focusable() bool { return f.Kind != kindStatic }

// revealed reports whether the secret on the focused row is currently shown.
// The set is keyed by label because the field table is rebuilt whenever the
// configuration is saved, and an index would then point somewhere else.
func (m Model) revealed(f field) bool { return m.shown[f.Label] }

// settlesOnBlur reports whether leaving a field has any effect on it, which is
// the one question esc answers here (Rule 130).
//
// A checkbox and an ordinary cycle field write as they are pressed, so there is
// nothing left to settle. The three that do not are a text field — the input
// holds the value until it is applied — and the forge and the secret backend,
// which are deliberately settled on the way out rather than on every ←→, so
// that cycling past a value does not close the session or ask three times.
func (m Model) settlesOnBlur(f field) bool {
	return f.takesText() || f.Label == forgeLabel || f.Label == secretBackendLabel ||
		f.Label == containerEngineLabel
}

// isDisabled reports whether a checkbox cannot move right now: a Trivy server
// that cannot do what it stands for, a category that is off, a tool whose
// dependency is not ticked.
func (m Model) isDisabled(f field) bool {
	return m.lockReason(f) != ""
}

// lockReason is why a checkbox cannot move, or "".
func (m Model) lockReason(f field) string {
	if f.locked == nil || m.config == nil {
		return ""
	}
	return f.locked(m.config)
}

// hint is what the footer says about a field while it has the focus. A
// checkbox says what it does in the state it is in — and why it cannot move,
// when it cannot — so the effect of space is read as it is pressed (§3.86).
// It is a state, not an event: it goes through Status, with no timer.
func (m Model) hint(f field) string {
	if reason := m.lockReason(f); reason != "" {
		return reason
	}
	if f.Kind == kindToggle && (f.hintOn != "" || f.hintOff != "") {
		if f.Bool(m.config) {
			return f.hintOn
		}
		return f.hintOff
	}
	return f.hint
}

// vocab is the wording of the forge this context targets, resolved from the
// config it is editing. It is what keeps a message about "the GitLab token"
// from saying GitLab in a GitHub context.
func (m Model) vocab() forge.Vocabulary {
	if m.config == nil {
		return forge.VocabularyFor("")
	}
	return forge.VocabularyFor(m.config.Forge.Type)
}

func cycle(label string, ref func(*config.Config) *string, options []string, hint string) field {
	return field{Label: label, Kind: kindCycle, str: ref, Options: options, hint: hint}
}

func static(label, value, hint string) field {
	return field{Label: label, Kind: kindStatic, fact: value, hint: hint}
}

func secret(label, value, hint string) field {
	return field{Label: label, Kind: kindSecret, fact: value, hint: hint}
}

// mcpState is the sentence the State row shows.
//
// The three cases are distinct on purpose: "not enabled" is a choice, "not
// started" is a failure, and an address is neither. Collapsing the first two
// into "off" would make a taken port look like a setting nobody turned on.
func mcpState(mcp MCPFacts) string {
	switch {
	case mcp.Addr != "":
		return "serving on http://" + mcp.Addr
	case mcp.Reason != "":
		return "not started — " + mcp.Reason
	default:
		return "not enabled for this context"
	}
}

// ── reading and writing ─────────────────────────────────────────────────────

// Value renders the setting as the text the field edits.
func (f field) Value(c *config.Config) string {
	switch f.Kind {
	case kindInteger:
		return strconv.Itoa(*f.num(c))
	case kindToggle:
		return strconv.FormatBool(f.Bool(c))
	case kindStatic, kindSecret:
		return f.fact
	default:
		if f.list != nil {
			return scan.JoinArgs(*f.list(c))
		}
		return *f.str(c)
	}
}

