package configuration

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/shared"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleBackendConfirmed()

	case sharedcomponents.ConfirmModalNoMsg:
		return m.handleBackendRejected()

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInput()
		m.keepFocusVisible()
		return m, nil

	// The router's detection (§3.86), for the tools tab's headings.
	case shared.ScanToolsMsg:
		m.tools = msg.Report
		return m, nil

	case saveFailedMsg:
		log.Printf("ERROR [configuration] save: %v", msg.err)
		return m, m.footer.Error("Failed to save — check logs")

	case tea.KeyMsg:
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		next, cmd := m.handleKey(msg)
		if updated, ok := next.(Model); ok {
			updated.keepFocusVisible()
			next = updated
		}
		return next, cmd
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleKey routes a keystroke. Rule 135 assigns each key exactly one job, and
// a tabbed form is the layout that lets it: Tab switches section, ↑↓ moves
// between fields, ←→ cycles a closed set, Space toggles.
func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "tab":
		return m.switchTab(1)
	case "shift+tab":
		return m.switchTab(-1)
	case "up":
		return m.moveField(-1)
	case "down":
		return m.moveField(1)
	case "left":
		return m.cycleField(-1)
	case "right":
		return m.cycleField(1)
	case " ":
		return m.toggleField()
	case "esc":
		return m.commitField()
	case "ctrl+r":
		return m.requestDetection()
	}

	// Anything else belongs to the input when a text field has focus. Nothing
	// below this point may claim a printable key: a path or a URL can contain
	// any of them.
	if m.current().takesText() {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}
	return m, nil
}

// switchTab commits the field being edited before leaving, so a value typed and
// abandoned by pressing Tab is not lost.
func (m Model) switchTab(step int) (tea.Model, tea.Cmd) {
	m, cmd, ok := m.commitFocused()
	if !ok {
		return m, cmd
	}

	m.activeTab = (m.activeTab + step + len(m.sections)) % len(m.sections)
	m.focusedField = m.settleFocus(0, 1)
	m.bindInput()
	return m, cmd
}

// moveField changes the focused field, committing the one being left.
func (m Model) moveField(step int) (tea.Model, tea.Cmd) {
	m, cmd, ok := m.commitFocused()
	if !ok {
		return m, cmd
	}

	fields := m.fields()
	if len(fields) == 0 {
		return m, cmd
	}
	m.focusedField = m.settleFocus((m.focusedField+step+len(fields))%len(fields), step)
	m.bindInput()
	return m, cmd

// cycleField advances a closed-set field (Rule 132).
func (m Model) cycleField(step int) (tea.Model, tea.Cmd) {
	f := m.current()
	if f.Kind != kindCycle {
		return m, nil
	}
	f.Cycle(m.config, step)

	// The theme is the one setting whose effect is the screen itself, so it is
	// applied as it is cycled rather than on blur — otherwise the user is
	// choosing blind.
	if f.Label == themeLabel {
		return m, m.persist(saved{theme: true})
	}
	// The backend is confirmed on blur, so nothing is written here.
	if f.Label == secretBackendLabel {
		return m, nil
	}
	// The engine is settled on blur, same reasoning: cycling auto → docker →
	// podman would otherwise re-resolve three times, including on the way back
	// to where it started.
	if f.Label == containerEngineLabel {
		return m, nil
	}
	// The forge is settled on blur too, and for a related reason: cycling
	// through it would otherwise close the session once per keypress, including
	// on the way back to where it started.
	if f.Label == forgeLabel {
		// Touched: from here on, host detection leaves the field alone.
		m.forgeTouched = true
		return m, nil
	}
	return m, m.persist(saved{})
}

// toggleField flips a checkbox. Space is the only key that may (Rule 135).
func (m Model) toggleField() (tea.Model, tea.Cmd) {
	f := m.current()

	// A secret row is shown or hidden, and nothing is written: `space` is the
	// only key that toggles anything in a form (Rule 135), and revealing is a
	// toggle like any other.
	if f.Kind == kindSecret {
		if f.Value(m.config) == "" {
			return m, m.footer.Warn("There is no token — the MCP server is not running for this context")
		}
		m.shown[f.Label] = !m.shown[f.Label]
		return m, nil
	}

	if f.Kind != kindToggle {
		return m, nil
	}
	// A warning either way: nothing failed, the box simply cannot move now,
	// and saying why is the point (Rule 130).
	if reason := m.lockReason(f); reason != "" {
		return m, m.footer.Warn(reason)
	}
	if f.guard != nil {
		if reason := f.guard(m.config, !f.Bool(m.config)); reason != "" {
			return m, m.footer.Warn(reason)
		}
	}
	f.Toggle(m.config)
	return m, m.persist(saved{})
}

// saved says which settings this write touched that the router has to act on
// rather than merely rebuild views against.
type saved struct {
	theme bool
	// forgeChanged says the session this context holds was opened against
	// something the config no longer describes — a different host, or a
	// different platform. One flag for both, because the consequence is one:
	// the session is stale and the user has to sign in again.
	forgeChanged bool
	// engineChanged says the container engine has to be re-resolved before any
	// rebuilt view asks it for a list.
	engineChanged bool
}
}

// GetFooterHeight is the tab bar, a blank line and the info line (Rule 124).
func (m Model) GetFooterHeight() int { return 3 }

// RenderFooter draws the tab bar, then the hint or message line.
func (m Model) RenderFooter(width int) string {
	tabs := make([]theme.TabItem, 0, len(m.sections))
	for _, s := range m.sections {
		tabs = append(tabs, theme.TabItem{Label: s.Title})
	}
	tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTab), width)

	// The field's hint is the derived status: it is a permanent property of
	// where the cursor is, so it has no timer and any message displaces it.
	info := m.footer.View(width, sharedcomponents.Status{Text: m.hint(m.current())})

	return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
}

// GetShortcuts lists only what is not self-evident (Rules 130, 137, 138).
// ↑↓ and tab are deliberately absent.
// GetShortcuts lists the three controls a field can take, greying the two the
// focused field does not (Rule 130).
//
// It used to return one of three single-entry lists, so the column changed
// shape on every ↑↓ — in a form, where the cursor moves constantly. `←→` and
// `space` are greyed rather than refused with a message: they are controls, not
// actions, and a footer line on every stray arrow key in a form would be noise.
//
// `↑↓` is never greyed because it always moves; only its wording changes, since
// a cycle or a checkbox has already persisted by the time the cursor leaves.
//
// `esc` is announced although Rule 138 calls the key obvious, because what it
// does here is not: it saves without moving. It is greyed on exactly the fields
// where it would do nothing — the ones that have already written.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	field := m.current()

	move := "Move between fields"
	if field.takesText() {
		move = "Save and move on"
	}

	return []shortcut.Shortcut{
		{Key: "↑↓", Description: move},
		{Key: "←→", Description: "Change value", Disabled: field.Kind != kindCycle},
		{Key: "space", Description: "Toggle", Disabled: field.Kind != kindToggle},
		{Key: "esc", Description: "Save this field", Disabled: !m.settlesOnBlur(field)},
		{Key: "ctrl+r", Description: "Detect tools again", Disabled: !m.onToolsTab()},
		{Key: "?", Description: "Open help"},
	}
}

