package dockerfile

import (
	"io/fs"
	"path/filepath"
	"sort"
	"strings"
)

const (
	// maxFindDepth bounds how far below the root a Dockerfile is looked for:
	// a monorepo keeps them a few levels down, and a tree deeper than that is
	// vendored or generated.
	maxFindDepth = 4
	// maxFound bounds the answer, so a checkout that vendors hundreds of
	// example Dockerfiles cannot turn one keypress into hundreds of registry
	// requests.
	maxFound = 50
)

// skippedDirs are never entered: what a package manager or a VCS put there is
// not the project's own build.
var skippedDirs = map[string]bool{
	".git": true, "node_modules": true, "vendor": true, ".worktrees": true,
	".venv": true, "venv": true, "target": true, "dist": true, "build": true,
}

// IsDockerfileName reports whether a file name is one a container build reads:
// Dockerfile or Containerfile, with a suffix (Dockerfile.dev) or a prefix
// (api.Dockerfile). It is by name and never by content, as the viewer's kind
// detection is.
func IsDockerfileName(name string) bool {
	lower := strings.ToLower(name)
	for _, base := range []string{"dockerfile", "containerfile"} {
		if lower == base || strings.HasPrefix(lower, base+".") || strings.HasSuffix(lower, "."+base) {
			return true
		}
	}
	return false
}

// Find lists the Dockerfiles under root, as slash-separated paths relative to
// it, in path order. It reports whether the answer was cut at the bound.
func Find(root string) (paths []string, truncated bool, err error) {
	err = filepath.WalkDir(root, func(path string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			if path == root {
				return walkErr
			}
			return nil // an unreadable subdirectory is skipped, not fatal
		}
		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			return nil
		}
		if d.IsDir() {
			if rel != "." && (skippedDirs[d.Name()] || strings.Count(rel, string(filepath.Separator)) >= maxFindDepth) {
				return filepath.SkipDir
			}
			return nil
		}
		if IsDockerfileName(d.Name()) {
			paths = append(paths, filepath.ToSlash(rel))
		}
		return nil
	})
	if err != nil {
		return nil, false, err
	}
	sort.Strings(paths)
	if len(paths) > maxFound {
		return paths[:maxFound], true, nil
	}
	return paths, false, nil
}
// Package dockerfile reads the base images a Dockerfile builds on, and where in
// the file each one is written.
//
// It exists for the security remediation (§3.2): a scan says which packages are
// vulnerable, and the Dockerfile is where the base image that carries them is
// named. Every image it reports comes with the byte range that spells it, so a
// later edit replaces those bytes and nothing else — comments, line endings and
// the rest of the file are never re-serialized.
//
// It is a reader, not a validator. It does not run the instructions, does not
// know about --build-arg overrides, and a Dockerfile it cannot make sense of
// yields fewer stages rather than an error.
package dockerfile

import (
	"regexp"
	"strings"

	"github.com/anthnel/devdesk/internal/patch"
)

// Span is patch.Span: a range of bytes, End exclusive. It is spelled here as
// well so a reader of this file does not have to go looking, and because every
// span this parser produces exists to be handed to patch.Rewrite.
type Span = patch.Span

// Kind says what a FROM instruction names.
type Kind int

const (
	// KindImage is an image reference, resolved or not.
	KindImage Kind = iota
	// KindScratch is `FROM scratch`: the empty image, nothing to scan or bump.
	KindScratch
	// KindStage is a FROM that names an earlier stage of the same file.
	KindStage
)

// Stage is one FROM instruction.
type Stage struct {
	// Line is the 1-based line of the FROM keyword.
	Line int
	// Name is the `AS name` of the stage, empty if it has none.
	Name string
	// Platform is the --platform flag as written (possibly a variable).
	Platform string
	Kind     Kind
	// Written is the image token exactly as it appears after FROM, so a view
	// can show `${BASE}` next to what it resolves to.
	Written string
	// Image is the reference once build args are substituted. Empty for a
	// scratch or stage FROM, and when Unresolved says why it could not be.
	Image      string
	Unresolved string
	// Span is where the image is spelled, and Editable says whether replacing
	// those bytes changes this stage's image. When the reference comes from an
	// ARG default, Span is that default's value in the ARG line: the one place
	// the image is actually written. Several stages can share it.
	Span         Span
	Editable     bool
	NoEditReason string
}

// File is a parsed Dockerfile.
type File struct {
	Stages []Stage
}

// argValue is a global ARG (declared before the first FROM) and where its
// default is written.
type argValue struct {
	value      string
	hasDefault bool
	span       Span
}

type line struct {
	off  int
	text string
}

type piece struct {
	off  int
	text string
}

type token struct {
	span Span
	text string
}

var directive = regexp.MustCompile(`^#\s*([A-Za-z]+)\s*=\s*(\S+)\s*$`)

// Parse reads the FROM instructions of a Dockerfile.
func Parse(content []byte) File {
	lines := splitLines(content)
	esc := escapeChar(lines)

	var file File
	args := map[string]argValue{}
	names := map[string]bool{}
	inStage := false

	for i := 0; i < len(lines); {
		trimmed := strings.TrimSpace(lines[i].text)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			i++
			continue
		}
		first := i
		pieces, next := gather(lines, i, esc)
		i = next
		tokens := tokenize(pieces)
		if len(tokens) == 0 {
			continue
		}
		switch strings.ToUpper(tokens[0].text) {
		case "ARG":
			if !inStage {
				readArgs(tokens[1:], args)
			}
		case "FROM":
			stage := readFrom(tokens[1:], args, names)
			stage.Line = first + 1
			file.Stages = append(file.Stages, stage)
			if stage.Name != "" {
				names[strings.ToLower(stage.Name)] = true
			}
			inStage = true
		}
	}
	return file
}

// splitLines cuts content into physical lines, keeping each one's byte offset.
// A trailing \r is dropped from the text but the offsets stay absolute.
func splitLines(b []byte) []line {
	var lines []line
	start := 0
	for i := 0; i <= len(b); i++ {
		if i < len(b) && b[i] != '\n' {
			continue
		}
		if i == len(b) && start == len(b) {
			break
		}
		text := string(b[start:i])
		text = strings.TrimSuffix(text, "\r")
		lines = append(lines, line{off: start, text: text})
		start = i + 1
	}
	return lines
}

// escapeChar reads the `# escape=` parser directive, which only counts at the
// very top of the file.
func escapeChar(lines []line) byte {
	for _, l := range lines {
		m := directive.FindStringSubmatch(strings.TrimSpace(l.text))
		if m == nil {
			break
		}
		if strings.EqualFold(m[1], "escape") && len(m[2]) == 1 && (m[2] == "`" || m[2] == `\`) {
			return m[2][0]
		}
	}
	return '\\'
}

// gather collects the physical lines of the instruction starting at lines[i],
// following the escape character across line breaks. Comment and blank lines
// inside a continuation are skipped, as Docker does.
func gather(lines []line, i int, esc byte) (pieces []piece, next int) {
	for i < len(lines) {
		text := strings.TrimRight(lines[i].text, " \t")
		if text == "" || text[len(text)-1] != esc {
			pieces = append(pieces, piece{off: lines[i].off, text: lines[i].text})
			return pieces, i + 1
		}
		pieces = append(pieces, piece{off: lines[i].off, text: text[:len(text)-1]})
		i++
		for i < len(lines) {
			t := strings.TrimSpace(lines[i].text)
			if t != "" && !strings.HasPrefix(t, "#") {
				break
			}
			i++
		}
	}
	return pieces, i
}

// tokenize splits pieces on spaces and tabs, with absolute byte spans.
func tokenize(pieces []piece) []token {
	var tokens []token
	for _, p := range pieces {
		start := -1
		for j := 0; j <= len(p.text); j++ {
			space := j == len(p.text) || p.text[j] == ' ' || p.text[j] == '\t'
			switch {
			case !space && start < 0:
				start = j
			case space && start >= 0:
				tokens = append(tokens, token{
					span: Span{Start: p.off + start, End: p.off + j},
					text: p.text[start:j],
				})
				start = -1
			}
		}
	}
	return tokens
}

// readArgs records `ARG NAME[=default] ...` into args. A later declaration of
// the same name replaces the earlier one, as it does for a following FROM.
func readArgs(tokens []token, args map[string]argValue) {
	for _, t := range tokens {
		name, value, hasDefault := strings.Cut(t.text, "=")
		if name == "" {
			continue
		}
		a := argValue{}
		if hasDefault {
			start := t.span.Start + len(name) + 1
			end := t.span.End
			if len(value) >= 2 && (value[0] == '"' || value[0] == '\'') && value[len(value)-1] == value[0] {
				value = value[1 : len(value)-1]
				start++
				end--
			}
			a = argValue{value: value, hasDefault: true, span: Span{Start: start, End: end}}
		}
		args[name] = a
	}
}

// readFrom reads what follows the FROM keyword: flags, the image, `AS name`.
func readFrom(tokens []token, args map[string]argValue, names map[string]bool) Stage {
	var st Stage
	i := 0
	for i < len(tokens) && strings.HasPrefix(tokens[i].text, "--") {
		if k, v, ok := strings.Cut(tokens[i].text, "="); ok && strings.EqualFold(k, "--platform") {
			st.Platform = v
		}
		i++
	}
	if i >= len(tokens) {
		st.Unresolved = "FROM names no image"
		return st
	}
	image := tokens[i]
	if i+2 < len(tokens) && strings.EqualFold(tokens[i+1].text, "AS") {
		st.Name = tokens[i+2].text
	}
	st.Written = image.text

	switch {
	case strings.EqualFold(image.text, "scratch"):
		st.Kind = KindScratch
	case names[strings.ToLower(image.text)]:
		st.Kind = KindStage
	default:
		resolveImage(&st, image, args)
	}
	return st
}

// resolveImage fills in Image, Span and Editable for an image token.
func resolveImage(st *Stage, image token, args map[string]argValue) {
	resolved, ok, sole := expand(image.text, args)
	if !ok {
		st.Unresolved = "the reference uses a build arg with no default"
		return
	}
	st.Image = resolved
	if !strings.Contains(image.text, "$") {
		st.Span, st.Editable = image.span, true
		return
	}
	if sole != nil && sole.hasDefault {
		// The whole reference is one variable: the default in its ARG line is
		// where the image is written. A --build-arg on the command line can
		// still override it, which a file cannot show.
		st.Span, st.Editable = sole.span, true
		return
	}
	st.NoEditReason = "the reference is assembled from build args, so no single place in the file spells it"
}

var reference = regexp.MustCompile(`\$(?:\{([A-Za-z_][A-Za-z0-9_]*)(?:(:?-)([^}]*))?\}|([A-Za-z_][A-Za-z0-9_]*))`)

// expand substitutes ${NAME}, $NAME, ${NAME:-default} and ${NAME-default}
// from the global ARGs. ok is false when a variable has no value; sole is the
// ARG when s is nothing but one reference to it.
func expand(s string, args map[string]argValue) (out string, ok bool, sole *argValue) {
	ok = true
	whole := reference.FindStringSubmatchIndex(s)
	out = reference.ReplaceAllStringFunc(s, func(m string) string {
		sub := reference.FindStringSubmatch(m)
		name := sub[1]
		if name == "" {
			name = sub[4]
		}
		a, declared := args[name]
		switch {
		case declared && a.hasDefault && (a.value != "" || sub[2] != ":-"):
			return a.value
		case sub[2] != "":
			return sub[3]
		}
		ok = false
		return m
	})
	if whole != nil && whole[0] == 0 && whole[1] == len(s) {
		sub := reference.FindStringSubmatch(s)
		name := sub[1]
		if name == "" {
			name = sub[4]
		}
		if a, declared := args[name]; declared {
			sole = &a
		}
	}
	return out, ok, sole
}

package remediation

import (
	"regexp"
	"strings"

	"github.com/anthnel/devdesk/internal/dockerfile"
	"github.com/anthnel/devdesk/internal/patch"
	"github.com/anthnel/devdesk/internal/scan"
)

// A misconfiguration is not fixed the way a vulnerability is (§3.78). Trivy
// reports the block it faults and a Resolution written in English — a sentence,
// not a replacement — so there is no general way to turn one into an edit.
//
// What there is instead is a **deliberately finite** catalog: the few rules that
// recur often enough to be worth writing by hand, each with the exact edit that
// satisfies it. A rule absent from the catalog is not a gap to be filled. It is
// the case the MCP server already covers, by handing a calling agent the span,
// the wording and the file (phase A) and re-measuring afterwards.
//
// That boundary is the point, and it is why Fix declines instead of
// approximating: an absence sends the user to something that works, while a
// doubtful edit sends them to a diff they have to second-guess.

// Rule is one misconfiguration this application knows how to fix on its own.
type Rule struct {
	// AVDID is the rule's identity as Trivy reports it in Finding.ID. It is
	// matched loosely — see ruleKey — because Trivy spells the same rule
	// "AVD-DS-0002" in one field and "DS002" in another.
	AVDID string
	// Title is what the UI calls the fix. It says what the edit does, not what
	// the rule forbids: the user is agreeing to a change, not reading an advisory.
	Title string
	// Fix returns the edits that satisfy the rule on content, or nil and a
	// reason when this instance is not one the catalog handles.
	//
	// It never guesses. An instance it cannot read exactly is one it declines,
	// and the reason is shown to the user as-is (Rule 129: English).
	Fix func(content []byte, f scan.Finding) ([]patch.Edit, string)
}

// The reasons a fix declines. They are constants because the view, the footer
// and the tests all read them, and a wording that drifts between the three is a
// wording that cannot be tested.
const (
	ReasonNoFixForRule   = "No built-in fix for this rule — use the MCP server and an agent"
	ReasonNotADockerfile = "The catalog only fixes Dockerfiles"
	ReasonNoStage        = "This Dockerfile declares no build stage"
	ReasonAlreadyFixed   = "The final stage already sets a user"
	ReasonUnreadableSpan = "The reported lines are not in this file"
	// ReasonUnknownBaseFamily is the one that matters: the account has to be
	// created before it can be used, and the command that creates it differs
	// between distributions. See fixRootUser.
	ReasonUnknownBaseFamily = "Cannot tell which distribution the final stage builds on, so the adduser flags cannot be chosen"
	// ReasonNoAptGetInstall fires when the reported lines no longer contain an
	// apt-get install — the file changed since the finding was reported. The
	// package-manager siblings below are the same reason for their own command.
	ReasonNoAptGetInstall   = "The reported lines do not contain an apt-get install"
	ReasonNoApkAdd          = "The reported lines do not contain an apk add"
	ReasonNoYumInstall      = "The reported lines do not contain a yum install"
	ReasonNoDnfInstall      = "The reported lines do not contain a dnf install"
	ReasonNoMicrodnfInstall = "The reported lines do not contain a microdnf install"
	ReasonNoZypperInstall   = "The reported lines do not contain a zypper install"
	// ReasonNotAnAddInstruction and ReasonAddExtractsOrFetches guard
	// fixAddInsteadOfCopy: the first refuses a stale line reference, the second
	// refuses an ADD that COPY genuinely cannot replace.
	ReasonNotAnAddInstruction  = "The reported line is not an ADD instruction"
	ReasonAddExtractsOrFetches = "This ADD extracts an archive or fetches a URL, which COPY cannot do"
	// ReasonNotACopyInstruction and ReasonCopyHasTooFewArgs guard
	// fixCopyMissingTrailingSlash the same way.
	ReasonNotACopyInstruction = "The reported line is not a COPY instruction"
	ReasonCopyHasTooFewArgs   = "This COPY has two or fewer arguments, so the destination is unambiguous without a trailing slash"
	// ReasonNotAMaintainerInstruction and ReasonMaintainerContinues guard
	// fixMaintainerDeprecated.
	ReasonNotAMaintainerInstruction = "The reported line is not a MAINTAINER instruction"
	ReasonMaintainerContinues       = "The MAINTAINER instruction continues onto another line"
)

// The account the fix creates. The uid goes through an ARG so it can be
// overridden at build time without editing the file again, which is what
// `docker init` generates and what makes the value a default rather than a
// decision taken on the user's behalf.
const (
	nonRootUser = "appuser"
	nonRootUID  = "10001"
)

// catalog is keyed by ruleKey, and it is short on purpose. Adding an entry means
// having seen the rule recur and having an edit that is exactly right for it;
// anything less belongs to the agent path.
//
// It stays short on purpose. Every entry is a textual edit whose correctness
// does not depend on guessing what the image is for — a flag insertion, an
// append, or a keyword swap that Trivy's own check already proved is safe by
// the shape of what it flagged. The candidates not in it were each rejected
// for a stated reason:
//
//   - a missing HEALTHCHECK (AVD-DS-0026) has no universal command — what to
//     probe depends on what the image runs, which the Dockerfile does not say;
//   - a `:latest` base image (AVD-DS-0001) is already the Remediation tab's job
//     (§3.2), which resolves real tags from the registry rather than inventing
//     one, and a second path to the same edit could only disagree with the
//     first;
//   - `apt-get dist-upgrade` (AVD-DS-0024) is deprecated in Trivy's own check
//     set, so a Dockerfile stops being flagged for it on its own;
//   - a self-referencing `COPY --from` (0006), a duplicate FROM alias (0012), an
//     EXPOSE port out of range (0008) or set to 22 (0004), `RUN cd` instead of
//     WORKDIR (0013), both wget and curl in use (0014), and a package-manager
//     `update` with no matching `install` in the same RUN (0017) are all real
//     defects or real decisions, and none of them names what the fix should be —
//     only the Dockerfile's author knows the other stage, the intended port, the
//     tool to keep, or the packages to install;
//   - duplicate ENTRYPOINT/CMD/HEALTHCHECK (0007, 0016, 0023), an unabsolute
//     WORKDIR (0009) and `sudo` in a RUN (0010) are each safe in principle —
//     only the last instruction of its kind takes effect, WORKDIR can be
//     resolved against the stage's own chain, and `sudo` is a no-op before any
//     USER switch — but none of that is tracked by this package yet: it reads
//     FROM, ARG and (for these fixes) the raw line range Trivy reports, not a
//     stage's running instruction history. Candidates for a later pass once
//     that tracking exists, not for this one.
var catalog = map[string]Rule{
	RuleKey("AVD-DS-0002"): {
		AVDID: "AVD-DS-0002",
		Title: "Add a USER instruction to the final stage",
		Fix:   fixRootUser,
	},
	RuleKey("AVD-DS-0005"): {
